import {brotliDecompressSync} from 'node:zlib';
// 固定Git夹具仅无损解码数据，不执行源码；原JSON SHA-256 47cbe59f09bd1f3c23fffb54373d1d0eb535fd7dc8b2ea6eea8df664bc036bf9。
import {describe,it,expect} from 'vitest';
import {parse} from 'acorn';
import {collectBuildSources} from '../existing-ops-build-source.js';
// 独立固定 Git 原始字节（1d811 / 020d）；仅解析，不执行候选。
const fixture = JSON.parse(brotliDecompressSync(Buffer.from('', 'base64')).toString('utf8'));
const P='packages/brain/scripts/coding-workflow/';
const stages=['intent','spec','spec-review','verify','evaluate'];
const entries=stages.map(s=>P+`activities/${s}.mjs`);
const prompts=['spec','spec-review','evaluate','evaluate-local'].map(s=>P+`prompts/${s}.md`);
const ast=text=>parse(text,{ecmaVersion:'latest',sourceType:'module'});
async function collect(version='recorded',mutate=()=>{},selected=/.*/){
 const sources=structuredClone(fixture.sources[version]);mutate(sources);
 const bindings=new Set(),gaps=[],relations=[];
 const readSource=async path=>{if(!(path in sources))throw Error('missing fixture '+path);return sources[path];};
 await collectBuildSources({parse:ast,paths:Object.keys(sources),selectors:{include:[selected],exclude:[]},revision:fixture.provenance[version],readSource,
  read:async path=>{if(!(path in sources)){gaps.push({code:'source_unavailable',path});return null;}bindings.add(path);return sources[path];},
  relations,requireProof:(value,code)=>{if(!value)gaps.push({code});return Boolean(value);}});
 return {bindings:[...bindings],gaps,relations};
}
const change=(s,path,before,after)=>{expect(s[P+path]).toContain(before);s[P+path]=s[P+path].replace(before,after);};
describe('固定真实阶段消费者来源',()=>{
 it('旧版本保持原build/publish图，不回写历史活动绑定',async()=>{const r=await collect('legacy');expect(r.gaps).toEqual([]);for(const path of entries)expect(r.bindings).not.toContain(path);});
 it('真实020d五活动四模板均有消费绑定和边',async()=>{const r=await collect();expect(r.gaps).toEqual([]);for(const path of [...entries,...prompts]){expect(r.bindings).toContain(path);expect(r.relations.some(e=>e.input_path===path)).toBe(true);}expect(new Set(r.relations.map(e=>JSON.stringify(e))).size).toBe(r.relations.length);});
 for(const name of ['spec','evaluate'])it(`仅选${name}不借未选build或其它stage`,async()=>{const r=await collect('recorded',()=>{},new RegExp(`/__tests__/${name}\\.test\\.mjs$`));expect(r.gaps).toEqual([]);expect(r.bindings).toContain(P+`activities/${name}.mjs`);for(const other of ['build',...stages.filter(s=>s!==name)]){expect(r.bindings).not.toContain(P+`activities/${other}.mjs`);expect(r.bindings).not.toContain(P+`__tests__/${other}.test.mjs`);}});
 it('仅选spec仍登记协议实际消费的provenance闭包',async()=>{const r=await collect('recorded',()=>{},/\/__tests__\/spec\.test\.mjs$/);for(const name of ['activity-provenance','record-provenance','record-provenance-store','record-provenance-records','provenance-path']){const p=P+`lib/${name}.mjs`;expect(r.bindings).toContain(p);expect(r.relations.some(e=>e.input_path===p)).toBe(true);}});
 it('evaluate两模式分别消费模板及真实repos配置',async()=>{const r=await collect('recorded',()=>{},/\/__tests__\/evaluate\.test\.mjs$/);for(const path of ['repos.json','lib/repo-profile.mjs','prompts/evaluate.md','prompts/evaluate-local.md'])expect(r.bindings).toContain(P+path);});
 const mutations=[
  ['skip-only',s=>{s[P+'__tests__/spec.test.mjs']=s[P+'__tests__/spec.test.mjs'].replaceAll("it('","it.skip('");}],
  ['todo',s=>change(s,'__tests__/verify.test.mjs',"it('verify-pass：","it.todo('verify-pass：")],
  ['test前置return',s=>change(s,'__tests__/spec.test.mjs',"const r = await run('ok');","return; const r = await run('ok');")],
  ['注册期退出',s=>{s[P+'__tests__/intent.test.mjs']+='\nprocess.exit(0);';}],
  ['私有helper',s=>change(s,'__tests__/spec.test.mjs',"import { runActivityProcess } from './helpers/run-activity.mjs';","const runActivityProcess = async () => ({exitCode:0});")],
  ['ENTRY假文件',s=>change(s,'__tests__/spec.test.mjs',"'../activities/spec.mjs'","'fixtures/fake-claude.mjs'")],
  ['ENTRY重绑',s=>{s[P+'__tests__/spec.test.mjs']+='\nENTRY="fake.mjs";';}],
  ['helper忽略entry',s=>change(s,'__tests__/helpers/run-activity.mjs','[entry]','["fake.mjs"]')],
  ['helper无spawn',s=>change(s,'__tests__/helpers/run-activity.mjs','spawn(process.execPath, [entry]','fakeSpawn(process.execPath, [entry]')],
  ['protocol不调用handler',s=>change(s,'lib/protocol.mjs','await handler(input)','({status:"completed"})')],
  ['阶段前置throw',s=>change(s,'activities/spec.mjs','await runActivity(async (input) => {','await runActivity(async (input) => { throw Error("dead");')],
  ['阶段伪完成',s=>change(s,'activities/intent.mjs','await runActivity(async (input) => {','await runActivity(async (input) => { return {status:"completed"};')],
  ['新旧混配',s=>{s[P+'activities/spec.mjs']=fixture.sources.legacy[P+'activities/spec.mjs'];}],
  ['旧stage搭新support',s=>{for(const path of entries)s[path]=fixture.sources.legacy[path];}],
  ['未知旧不能降级',s=>{for(const path of entries)s[path]=fixture.sources.legacy[path];s[entries[0]]+='\nthrow Error("unknown");';}],
  ['新入口缺失',s=>{delete s[P+'activities/verify.mjs'];}],
  ['spec错模板',s=>change(s,'activities/spec.mjs',"loadPrompt('spec',","loadPrompt('build',")],
  ['spec丢模板',s=>change(s,'activities/spec.mjs',"['-p', prompt,","['-p', 'fake',")],
  ['review错role',s=>change(s,'activities/spec-review.mjs',"spec_review: 'spec-review'","spec_review: 'spec-revise'")],
  ['review丢模板',s=>change(s,'activities/spec-review.mjs',"args: ['-p', prompt,","args: ['-p', 'fake',")],
  ['evaluate仅preview',s=>change(s,'__tests__/evaluate.test.mjs',"it('不查预览环境（预览不存在也照验）","it.skip('不查预览环境（预览不存在也照验）")],
  ['local提前return',s=>change(s,'__tests__/evaluate.test.mjs',"preview = null;\n      const r = await run('pass', { repo_profile: ZJ });","return; preview = null;\n      const r = await run('pass', { repo_profile: ZJ });")],
  ['local配置变preview',s=>{const p=P+'repos.json',v=JSON.parse(s[p]);v.repos.find(r=>r.key==='zenithjoy-workspace').preview.type='brain_preview';s[p]=JSON.stringify(v);}],
  ['qaMode替身',s=>change(s,'lib/repo-profile.mjs',"return profileOf(profile).preview?.type ?? 'brain_preview';","return 'brain_preview';")],
  ['evaluate丢模板',s=>change(s,'activities/evaluate.mjs',"['-p', prompt,","['-p', 'fake',")],
  ['native reader替身',s=>change(s,'lib/claude.mjs','return renderPrompt(fs.readFileSync','return fakeRender(fs.readFileSync')],
  ['reader未导出',s=>change(s,'lib/claude.mjs','export function loadPrompt','function loadPrompt')],
 ];
 for(const [name,mutate] of mutations)it(`${name}拒绝来源认领`,async()=>{const r=await collect('recorded',mutate);expect(r.gaps.length).toBeGreaterThan(0);for(const path of [...entries,...prompts])expect(r.bindings).not.toContain(path);});
 it('恶意候选只解析AST绝不执行',async()=>{const r=await collect('recorded',s=>{s[P+'activities/spec.mjs']+='\nglobalThis.__stageCandidateExecuted=true;';});expect(globalThis.__stageCandidateExecuted).toBeUndefined();expect(r.gaps.length).toBeGreaterThan(0);});
});
